// Music, ambience, positional sound effects and UI sounds, with separate volumes for each.
// Clips are the WAV files generated by tools/synth_audio.py into Resources/Audio.
// Music crossfades between tracks; "dynamic music" raises the night track's intensity
// with the size of the wave.
using System.Collections;
using System.Collections.Generic;
using Rigfall.Core;
using UnityEngine;

namespace Rigfall.Runtime
{
    public sealed class AudioService : MonoBehaviour
    {
        static AudioService instance;

        readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>();
        AudioSource musicA, musicB, ambience, ui;
        readonly List<AudioSource> sfxPool = new List<AudioSource>();
        int sfxNext;
        bool musicOnA = true;
        string currentTrack = "";
        string currentAmbience = "";
        float intensity;          // 0..1 for dynamic music
        int fadeVersion;          // a newer crossfade cancels an older one
        bool fading;
        bool focused = true;
        readonly Dictionary<string, float> lastPlayed = new Dictionary<string, float>();

        public static string CurrentTrack => instance != null ? instance.currentTrack : "";

        public static void Init(Transform parent)
        {
            if (instance != null) return;
            var go = new GameObject("Audio");
            go.transform.SetParent(parent, false);
            instance = go.AddComponent<AudioService>();
            instance.Setup();
        }

        void Setup()
        {
            musicA = NewSource("Music A", true);
            musicB = NewSource("Music B", true);
            ambience = NewSource("Ambience", true);
            ui = NewSource("UI", false);
            for (int i = 0; i < 24; i++)
            {
                var s = NewSource("Sfx " + i, false);
                s.spatialBlend = 0.65f;
                s.rolloffMode = AudioRolloffMode.Linear;
                s.minDistance = 8f;
                s.maxDistance = 60f;
                s.dopplerLevel = 0f;
                sfxPool.Add(s);
            }
        }

        AudioSource NewSource(string name, bool loop)
        {
            var go = new GameObject(name);
            go.transform.SetParent(transform, false);
            var s = go.AddComponent<AudioSource>();
            s.playOnAwake = false;
            s.loop = loop;
            s.spatialBlend = 0f;
            return s;
        }

        AudioClip Clip(string name)
        {
            if (string.IsNullOrEmpty(name)) return null;
            AudioClip c;
            if (clips.TryGetValue(name, out c)) return c;
            c = Resources.Load<AudioClip>("Audio/" + name);
            clips[name] = c;
            return c;
        }

        static GameSettings S => Game.Settings;

        // ---- sound effects ---------------------------------------------------------------

        /// <summary>Positional effect with a little random pitch so repeats don't sound robotic.</summary>
        public static void Sfx(string name, Vector3 position, float pitch = 1f, float volume = 1f)
        {
            if (instance == null) return;
            instance.PlaySfx(name, position, pitch, volume);
        }

        void PlaySfx(string name, Vector3 position, float pitch, float volume)
        {
            var clip = Clip(name);
            if (clip == null) return;
            // Throttle identical sounds within 40 ms (forty enemies dying in one frame is one sound).
            float last;
            if (lastPlayed.TryGetValue(name, out last) && Time.unscaledTime - last < 0.04f) return;
            lastPlayed[name] = Time.unscaledTime;
            var s = sfxPool[sfxNext];
            sfxNext = (sfxNext + 1) % sfxPool.Count;
            s.transform.position = position;
            s.spatialBlend = S.spatialAudio ? 0.65f : 0f;
            s.clip = clip;
            s.pitch = pitch * Random.Range(0.94f, 1.06f);
            s.volume = Mathf.Clamp01(volume * S.sfxVolume);
            s.Play();
        }

        /// <summary>Non-positional interface sound (clicks, coins, wheel ticks).</summary>
        public static void Ui(string name, float pitch = 1f, float volume = 1f)
        {
            if (instance == null) return;
            var clip = instance.Clip(name);
            if (clip == null) return;
            instance.ui.pitch = pitch;
            instance.ui.PlayOneShot(clip, Mathf.Clamp01(volume * S.uiVolume));
        }

        // ---- music & ambience ------------------------------------------------------------

        /// <summary>Crossfade to a track. Respects the player's chosen jukebox track if one is set.</summary>
        public static void Music(string track, float fade = 1.2f)
        {
            if (instance == null) return;
            if (!string.IsNullOrEmpty(S.musicTrack)) track = S.musicTrack;
            if (track == instance.currentTrack) return;
            instance.StartCoroutine(instance.Crossfade(track, fade));
        }

        /// <summary>Play a specific track regardless of the jukebox override (used by the jukebox itself).</summary>
        public static void Preview(string track)
        {
            if (instance == null) return;
            instance.StartCoroutine(instance.Crossfade(track, 0.6f));
        }

        IEnumerator Crossfade(string track, float fade)
        {
            int version = ++fadeVersion;
            fading = true;
            currentTrack = track;
            var clip = Clip(track);
            var from = musicOnA ? musicA : musicB;
            var to = musicOnA ? musicB : musicA;
            musicOnA = !musicOnA;
            to.clip = clip;
            to.volume = 0f;
            if (clip != null) to.Play();
            float t = 0f;
            float startFrom = from.volume;
            while (t < fade)
            {
                if (version != fadeVersion) yield break; // superseded: the newer fade takes over both sources
                t += Time.unscaledDeltaTime;
                float x = Mathf.Clamp01(t / fade);
                from.volume = startFrom * (1f - x);
                to.volume = MusicVolume() * x;
                yield return null;
            }
            from.Stop();
            to.volume = MusicVolume();
            fading = false;
        }

        public static void Ambience(string name)
        {
            if (instance == null || instance.currentAmbience == name) return;
            instance.currentAmbience = name;
            var clip = instance.Clip(name);
            instance.ambience.clip = clip;
            if (clip != null) instance.ambience.Play(); else instance.ambience.Stop();
        }

        /// <summary>0 = calm, 1 = the whole wave is on the pad. Only used when Dynamic Music is on.</summary>
        public static void SetIntensity(float value)
        {
            if (instance != null) instance.intensity = Mathf.Clamp01(value);
        }

        float MusicVolume()
        {
            float v = S.musicVolume;
            if (S.dynamicMusic) v *= Mathf.Lerp(0.8f, 1.1f, intensity);
            return Mathf.Clamp01(v);
        }

        void Update()
        {
            float master = S.masterVolume;
            if (S.muteWhenUnfocused && !focused) master = 0f;
            AudioListener.volume = master;
            var active = musicOnA ? musicA : musicB;
            if (active.isPlaying && !fading) active.volume = Mathf.MoveTowards(active.volume, MusicVolume(), Time.unscaledDeltaTime);
            active.pitch = Game.Paused ? 0.92f : 1f;
            ambience.volume = Mathf.Clamp01(S.ambienceVolume * (Game.Paused ? 0.4f : 1f));
        }

        void OnApplicationFocus(bool hasFocus) { focused = hasFocus; }
    }
}
